function ktTour(n, start){ n=n||8; if(n<1||n>30) return null; var N=n*n;
  var board=new Array(N).fill(-1);
  var moves=[[2,1],[1,2],[-1,2],[-2,1],[-2,-1],[-1,-2],[1,-2],[2,-1]];
  function inb(r,c){return r>=0&&r<n&&c>=0&&c<n;}
  function deg(r,c){ var d=0; for(var i=0;i<8;i++){ var nr=r+moves[i][0], nc=c+moves[i][1]; if(inb(nr,nc)&&board[nr*n+nc]===-1) d++; } return d; }
  function look(r,c){ var best=99; for(var i=0;i<8;i++){ var nr=r+moves[i][0], nc=c+moves[i][1]; if(inb(nr,nc)&&board[nr*n+nc]===-1){ var d=0; for(var j=0;j<8;j++){ var ar=nr+moves[j][0], ac=nc+moves[j][1]; if(inb(ar,ac)&&board[ar*n+ac]===-1) d++; } if(d<best) best=d; } } return best; }
  var budget=200000, used=0;
  function solve(r,c,step){ if(used++>budget) return false; board[r*n+c]=step; if(step===N-1) return true;
    var cands=[]; for(var i=0;i<8;i++){ var nr=r+moves[i][0], nc=c+moves[i][1]; if(inb(nr,nc)&&board[nr*n+nc]===-1) cands.push([nr,nc]); }
    cands.sort(function(a,b){ var da=deg(a[0],a[1])-deg(b[0],b[1]); if(da!==0) return da; return look(a[0],a[1])-look(b[0],b[1]); });
    for(var k=0;k<cands.length;k++){ if(solve(cands[k][0],cands[k][1],step+1)) return true; }
    board[r*n+c]=-1; return false; }
  function tryStart(s){ board.fill(-1); used=0; if(!inb(s[0],s[1])) return false; return solve(s[0],s[1],0); }
  var starts = start ? [start] : [];
  if(!start){ for(var r=0;r<n;r++) for(var c=0;c<n;c++) starts.push([r,c]); }
  for(var si=0; si<starts.length; si++){ if(tryStart(starts[si])){ var tour=new Array(N); for(var i=0;i<N;i++){ tour[board[i]]=[Math.floor(i/n), i%n]; } return tour; } }
  return null; }
var EXPORTS={ktTour:ktTour};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KnightTourForgePure = EXPORTS; }
